using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests
{
    public static class TestHelper
    {
        public static SchoolContext CreateContext(string dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;
            return new SchoolContext(options);
        }

        public static SchoolContext CreateSeededContext(string dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var context = CreateContext(dbName);
            SeedData(context);
            return context;
        }

        public static void SeedData(SchoolContext context)
        {
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 350000,
                StartDate = DateTime.Parse("2007-09-01")
            };
            context.Departments.Add(dept);

            var instructor = new Instructor
            {
                ID = 1,
                LastName = "Smith",
                FirstMidName = "John",
                HireDate = DateTime.Parse("2000-01-01"),
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { InstructorID = 1, Location = "Room 101" }
            };
            context.Instructors.Add(instructor);

            dept.InstructorID = instructor.ID;

            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1,
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };
            context.Courses.Add(course);

            var course2 = new Course
            {
                CourseID = 4022,
                Title = "Microeconomics",
                Credits = 3,
                DepartmentID = 1,
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };
            context.Courses.Add(course2);

            context.CourseAssignments.Add(new CourseAssignment
            {
                CourseID = 1050,
                InstructorID = 1
            });

            var student1 = new Student
            {
                ID = 1,
                LastName = "Alexander",
                FirstMidName = "Carson",
                EnrollmentDate = DateTime.Parse("2010-09-01"),
                Enrollments = new List<Enrollment>()
            };
            var student2 = new Student
            {
                ID = 2,
                LastName = "Alonso",
                FirstMidName = "Meredith",
                EnrollmentDate = DateTime.Parse("2012-09-01"),
                Enrollments = new List<Enrollment>()
            };
            var student3 = new Student
            {
                ID = 3,
                LastName = "Baker",
                FirstMidName = "Alice",
                EnrollmentDate = DateTime.Parse("2013-09-01"),
                Enrollments = new List<Enrollment>()
            };
            context.Students.AddRange(student1, student2, student3);

            context.Enrollments.Add(new Enrollment
            {
                EnrollmentID = 1,
                CourseID = 1050,
                StudentID = 1,
                Grade = Grade.A
            });

            context.SaveChanges();
        }
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests
    {
        private SchoolContext GetContext() => TestHelper.CreateSeededContext();

        [Fact]
        public void Index_ReturnsView_WithDefaultSort()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);

            var result = controller.Index(null, null, null, null) as ViewResult;

            Assert.NotNull(result);
            var model = result.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            // Default sort is by LastName ascending
            Assert.True(model.Count > 0);
            Assert.Equal("Alexander", model.First().LastName);
        }

        [Fact]
        public void Index_SortByNameDesc()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);

            var result = controller.Index("name_desc", null, null, null) as ViewResult;

            var model = result.Model as PaginatedList<Student>;
            Assert.Equal("Baker", model.First().LastName);
        }

        [Fact]
        public void Index_SortByDate()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);

            var result = controller.Index("Date", null, null, null) as ViewResult;

            var model = result.Model as PaginatedList<Student>;
            // Earliest date first
            Assert.Equal("Alexander", model.First().LastName);
        }

        [Fact]
        public void Index_SortByDateDesc()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);

            var result = controller.Index("date_desc", null, null, null) as ViewResult;

            var model = result.Model as PaginatedList<Student>;
            Assert.Equal("Baker", model.First().LastName);
        }

        [Fact]
        public void Index_SearchFilter_FiltersResults()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);

            var result = controller.Index(null, null, "Alexander", null) as ViewResult;

            var model = result.Model as PaginatedList<Student>;
            Assert.Single(model);
            Assert.Equal("Alexander", model.First().LastName);
        }

        [Fact]
        public void Index_SearchString_ResetsPage()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);

            var result = controller.Index(null, null, "A", null) as ViewResult;

            var model = result.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            // Page should be 1 when searchString is provided
            Assert.Equal(1, model.PageIndex);
        }

        [Fact]
        public void Index_UsesCurrentFilter_WhenNoSearchString()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);

            var result = controller.Index(null, "Baker", null, null) as ViewResult;

            var model = result.Model as PaginatedList<Student>;
            Assert.Single(model);
            Assert.Equal("Baker", model.First().LastName);
        }

        [Fact]
        public void Details_ReturnsNotFound_WhenIdIsNull()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);

            var result = controller.Details(null);

            Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
        }

        [Fact]
        public void Details_ReturnsView_WhenStudentExists()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);

            var result = controller.Details(1) as ViewResult;

            Assert.NotNull(result);
            var student = result.Model as Student;
            Assert.Equal("Alexander", student.LastName);
        }

        [Fact]
        public void Create_Get_ReturnsView()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);

            var result = controller.Create() as ViewResult;

            Assert.NotNull(result);
            var model = result.Model as Student;
            Assert.NotNull(model);
            Assert.Equal(DateTime.Today, model.EnrollmentDate);
        }

        [Fact]
        public void Create_Post_ValidStudent_RedirectsToIndex()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);
            var student = new Student
            {
                LastName = "NewStudent",
                FirstMidName = "Test",
                EnrollmentDate = DateTime.Parse("2023-01-15")
            };

            var result = controller.Create(student) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Equal(4, context.Students.Count());
        }

        [Fact]
        public void Create_Post_InvalidEnrollmentDate_ReturnsView()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);
            var student = new Student
            {
                LastName = "NewStudent",
                FirstMidName = "Test",
                EnrollmentDate = DateTime.MinValue
            };

            var result = controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.False(controller.ModelState.IsValid);
        }

        [Fact]
        public void Create_Post_DateOutOfRange_ReturnsView()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);
            var student = new Student
            {
                LastName = "NewStudent",
                FirstMidName = "Test",
                EnrollmentDate = new DateTime(1000, 1, 1)
            };

            var result = controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.False(controller.ModelState.IsValid);
        }

        [Fact]
        public void Edit_Get_ReturnsNotFound_WhenIdIsNull()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);

            var result = controller.Edit((int?)null);

            Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
        }

        [Fact]
        public void Edit_Get_ReturnsNotFound_WhenStudentNotFound()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);

            var result = controller.Edit(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Get_ReturnsView_WhenStudentExists()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);

            var result = controller.Edit(1) as ViewResult;

            Assert.NotNull(result);
            var student = result.Model as Student;
            Assert.Equal("Alexander", student.LastName);
        }

        [Fact]
        public void Edit_Post_ValidStudent_RedirectsToIndex()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);
            var student = new Student
            {
                ID = 1,
                LastName = "Updated",
                FirstMidName = "Carson",
                EnrollmentDate = DateTime.Parse("2010-09-01")
            };

            // Detach the existing entity to avoid tracking conflicts
            var existing = context.Students.Find(1);
            context.Entry(existing).State = EntityState.Detached;

            var result = controller.Edit(student) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Edit_Post_InvalidDate_ReturnsView()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);
            var student = new Student
            {
                ID = 1,
                LastName = "Updated",
                FirstMidName = "Carson",
                EnrollmentDate = DateTime.MinValue
            };

            var result = controller.Edit(student) as ViewResult;

            Assert.NotNull(result);
            Assert.False(controller.ModelState.IsValid);
        }

        [Fact]
        public void Delete_Get_ReturnsNotFound_WhenIdIsNull()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);

            var result = controller.Delete(null);

            Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
        }

        [Fact]
        public void Delete_Get_ReturnsNotFound_WhenStudentNotFound()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);

            var result = controller.Delete(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_Get_ReturnsView_WhenStudentExists()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);

            var result = controller.Delete(1) as ViewResult;

            Assert.NotNull(result);
            var student = result.Model as Student;
            Assert.Equal("Alexander", student.LastName);
        }

        [Fact]
        public void DeleteConfirmed_RemovesStudent_RedirectsToIndex()
        {
            using var context = GetContext();
            var controller = new StudentsController(context);

            var result = controller.DeleteConfirmed(1) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Equal(2, context.Students.Count());
        }
    }
}

