{"file_text": "using ContosoUniversity.Models;
using ContosoUniversity.Services;
using System;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests
    {
        [Fact]
        public void SendNotification_EnqueuesNotification()
        {
            using var service = new NotificationService();

            service.SendNotification("Student", "1", "Test Student", EntityOperation.CREATE, "Admin");

            var notification = service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Contains("Test Student", notification.Message);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesEntityId()
        {
            using var service = new NotificationService();

            service.SendNotification("Course", "42", EntityOperation.UPDATE);

            var notification = service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("ID: 42", notification.Message);
            Assert.Equal("UPDATE", notification.Operation);
        }

        [Fact]
        public void SendNotification_Delete_GeneratesCorrectMessage()
        {
            using var service = new NotificationService();

            service.SendNotification("Department", "5", "Science", EntityOperation.DELETE, "User1");

            var notification = service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("deleted", notification.Message);
            Assert.Contains("Science", notification.Message);
        }

        [Fact]
        public void SendNotification_Create_GeneratesCorrectMessage()
        {
            using var service = new NotificationService();

            service.SendNotification("Instructor", "10", "Dr. Smith", EntityOperation.CREATE);

            var notification = service.ReceiveNotification();
            Assert.Contains("created", notification.Message);
            Assert.Contains("Dr. Smith", notification.Message);
        }

        [Fact]
        public void SendNotification_Update_GeneratesCorrectMessage()
        {
            using var service = new NotificationService();

            service.SendNotification("Student", "3", "Jane Doe", EntityOperation.UPDATE);

            var notification = service.ReceiveNotification();
            Assert.Contains("updated", notification.Message);
            Assert.Contains("Jane Doe", notification.Message);
        }

        [Fact]
        public void ReceiveNotification_ReturnsNull_WhenQueueEmpty()
        {
            using var service = new NotificationService();

            // Drain any existing notifications from shared queue
            while (service.ReceiveNotification() != null) { }

            var result = service.ReceiveNotification();

            Assert.Null(result);
        }

        [Fact]
        public void SendNotification_WithNullUserName_DefaultsToSystem()
        {
            using var service = new NotificationService();

            service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, null);

            var notification = service.ReceiveNotification();
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_SetsCreatedAt()
        {
            using var service = new NotificationService();
            var before = DateTime.Now;

            service.SendNotification("Student", "1", EntityOperation.CREATE);

            var notification = service.ReceiveNotification();
            Assert.True(notification.CreatedAt >= before);
            Assert.True(notification.CreatedAt <= DateTime.Now);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            using var service = new NotificationService();

            // Should not throw (no-op implementation)
            var exception = Record.Exception(() => service.MarkAsRead(999));
            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();

            var exception = Record.Exception(() => service.Dispose());
            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_MultipleMessages_QueuedInOrder()
        {
            using var service = new NotificationService();

            service.SendNotification("A", "1", EntityOperation.CREATE);
            service.SendNotification("B", "2", EntityOperation.UPDATE);
            service.SendNotification("C", "3", EntityOperation.DELETE);

            var n1 = service.ReceiveNotification();
            var n2 = service.ReceiveNotification();
            var n3 = service.ReceiveNotification();

            // Queue is shared/static so we just verify we get notifications
            Assert.NotNull(n1);
            Assert.NotNull(n2);
            Assert.NotNull(n3);
        }

        [Fact]
        public void SendNotification_WithoutOverload_UsesNullDisplayName()
        {
            using var service = new NotificationService();

            service.SendNotification("Test", "99", EntityOperation.CREATE, "TestUser");

            var notification = service.ReceiveNotification();
            Assert.Contains("ID: 99", notification.Message);
            Assert.Equal("TestUser", notification.CreatedBy);
        }
    }
}
