{"file_text": "using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests
    {
        [Fact]
        public void CanCreateContext_WithInMemoryDatabase()
        {
            using var context = TestHelper.CreateContext();

            Assert.NotNull(context);
            Assert.NotNull(context.Students);
            Assert.NotNull(context.Courses);
            Assert.NotNull(context.Departments);
            Assert.NotNull(context.Instructors);
            Assert.NotNull(context.Enrollments);
            Assert.NotNull(context.CourseAssignments);
            Assert.NotNull(context.OfficeAssignments);
            Assert.NotNull(context.Notifications);
        }

        [Fact]
        public void CanAddAndRetrieveStudent()
        {
            using var context = TestHelper.CreateContext();
            var student = new Student
            {
                LastName = "Test",
                FirstMidName = "Student",
                EnrollmentDate = DateTime.Parse("2023-01-01")
            };

            context.Students.Add(student);
            context.SaveChanges();

            var retrieved = context.Students.First();
            Assert.Equal("Test", retrieved.LastName);
            Assert.Equal("Student", retrieved.FirstMidName);
        }

        [Fact]
        public void CanAddAndRetrieveCourse()
        {
            using var context = TestHelper.CreateContext();
            var dept = new Department { Name = "Test", Budget = 1000, StartDate = DateTime.Now };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course
            {
                CourseID = 101,
                Title = "Test Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            context.Courses.Add(course);
            context.SaveChanges();

            var retrieved = context.Courses.First();
            Assert.Equal("Test Course", retrieved.Title);
            Assert.Equal(3, retrieved.Credits);
        }

        [Fact]
        public void CourseAssignment_HasCompositeKey()
        {
            using var context = TestHelper.CreateContext();
            var instructor = new Instructor
            {
                LastName = "Test",
                FirstMidName = "Instr",
                HireDate = DateTime.Now
            };
            context.Instructors.Add(instructor);
            var dept = new Department { Name = "Test", Budget = 1000, StartDate = DateTime.Now };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course { CourseID = 200, Title = "Course", Credits = 3, DepartmentID = dept.DepartmentID };
            context.Courses.Add(course);
            context.SaveChanges();

            var assignment = new CourseAssignment { CourseID = 200, InstructorID = instructor.ID };
            context.CourseAssignments.Add(assignment);
            context.SaveChanges();

            var retrieved = context.CourseAssignments.First();
            Assert.Equal(200, retrieved.CourseID);
            Assert.Equal(instructor.ID, retrieved.InstructorID);
        }

        [Fact]
        public void OfficeAssignment_HasInstructorIdAsKey()
        {
            using var context = TestHelper.CreateContext();
            var instructor = new Instructor
            {
                LastName = "Test",
                FirstMidName = "Instr",
                HireDate = DateTime.Now
            };
            context.Instructors.Add(instructor);
            context.SaveChanges();

            var office = new OfficeAssignment { InstructorID = instructor.ID, Location = "Room 1" };
            context.OfficeAssignments.Add(office);
            context.SaveChanges();

            var retrieved = context.OfficeAssignments.First();
            Assert.Equal(instructor.ID, retrieved.InstructorID);
            Assert.Equal("Room 1", retrieved.Location);
        }

        [Fact]
        public void CanAddNotification()
        {
            using var context = TestHelper.CreateContext();
            var notification = new Notification
            {
                EntityType = "Student",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test message",
                CreatedAt = DateTime.Now,
                CreatedBy = "System",
                IsRead = false
            };

            context.Notifications.Add(notification);
            context.SaveChanges();

            var retrieved = context.Notifications.First();
            Assert.Equal("Student", retrieved.EntityType);
            Assert.Equal("CREATE", retrieved.Operation);
        }

        [Fact]
        public void Enrollment_HasRelationships()
        {
            using var context = TestHelper.CreateSeededContext();

            var enrollment = context.Enrollments
                .Include(e => e.Course)
                .Include(e => e.Student)
                .First();

            Assert.NotNull(enrollment.Course);
            Assert.NotNull(enrollment.Student);
            Assert.Equal(Grade.A, enrollment.Grade);
        }
    }

    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_SeedsDatabase()
        {
            using var context = TestHelper.CreateContext();

            DbInitializer.Initialize(context);

            Assert.True(context.Students.Any());
            Assert.True(context.Instructors.Any());
            Assert.True(context.Departments.Any());
            Assert.True(context.Courses.Any());
            Assert.True(context.Enrollments.Any());
            Assert.True(context.CourseAssignments.Any());
            Assert.True(context.OfficeAssignments.Any());
        }

        [Fact]
        public void Initialize_DoesNotDuplicate_WhenCalledTwice()
        {
            var dbName = Guid.NewGuid().ToString();
            using var context = TestHelper.CreateContext(dbName);

            DbInitializer.Initialize(context);
            var studentCount = context.Students.Count();

            DbInitializer.Initialize(context);
            Assert.Equal(studentCount, context.Students.Count());
        }
    }
}
