using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests
    {
        private SchoolContext GetContext() => TestHelper.CreateSeededContext();

        [Fact]
        public void Index_ReturnsView_WithInstructorData()
        {
            using var context = GetContext();
            var controller = new InstructorsController(context);

            var result = controller.Index(null, null) as ViewResult;

            Assert.NotNull(result);
            var model = result.Model as Models.SchoolViewModels.InstructorIndexData;
            Assert.NotNull(model);
            Assert.NotNull(model.Instructors);
            Assert.Single(model.Instructors);
        }

        [Fact]
        public void Index_WithInstructorId_PopulatesCourses()
        {
            using var context = GetContext();
            var controller = new InstructorsController(context);

            var result = controller.Index(1, null) as ViewResult;

            var model = result.Model as Models.SchoolViewModels.InstructorIndexData;
            Assert.NotNull(model.Courses);
            Assert.Single(model.Courses);
        }

        [Fact]
        public void Index_WithCourseId_PopulatesEnrollments()
        {
            using var context = GetContext();
            var controller = new InstructorsController(context);

            var result = controller.Index(1, 1050) as ViewResult;

            var model = result.Model as Models.SchoolViewModels.InstructorIndexData;
            Assert.NotNull(model.Enrollments);
        }

        [Fact]
        public void Details_ReturnsBadRequest_WhenIdIsNull()
        {
            using var context = GetContext();
            var controller = new InstructorsController(context);

            var result = controller.Details(null);

            Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
        }

        [Fact]
        public void Details_ReturnsNotFound_WhenInstructorNotFound()
        {
            using var context = GetContext();
            var controller = new InstructorsController(context);

            var result = controller.Details(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Details_ReturnsView_WhenInstructorExists()
        {
            using var context = GetContext();
            var controller = new InstructorsController(context);

            var result = controller.Details(1) as ViewResult;

            Assert.NotNull(result);
            var instructor = result.Model as Instructor;
            Assert.Equal("Smith", instructor.LastName);
        }

        [Fact]
        public void Create_Get_ReturnsView()
        {
            using var context = GetContext();
            var controller = new InstructorsController(context);

            var result = controller.Create() as ViewResult;

            Assert.NotNull(result);
            var model = result.Model as Instructor;
            Assert.NotNull(model);
            Assert.NotNull(model.CourseAssignments);
        }

        [Fact]
        public void Create_Post_ValidInstructor_RedirectsToIndex()
        {
            using var context = GetContext();
            var controller = new InstructorsController(context);
            var instructor = new Instructor
            {
                LastName = "NewInstructor",
                FirstMidName = "Jane",
                HireDate = DateTime.Parse("2020-01-01"),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = controller.Create(instructor, null) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Equal(2, context.Instructors.Count());
        }

        [Fact]
        public void Create_Post_WithSelectedCourses_AssignsCourses()
        {
            using var context = GetContext();
            var controller = new InstructorsController(context);
            var instructor = new Instructor
            {
                LastName = "NewInstructor",
                FirstMidName = "Jane",
                HireDate = DateTime.Parse("2020-01-01"),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = controller.Create(instructor, new[] { "1050" }) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Create_Post_InvalidModel_ReturnsView()
        {
            using var context = GetContext();
            var controller = new InstructorsController(context);
            controller.ModelState.AddModelError("LastName", "Required");
            var instructor = new Instructor
            {
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = controller.Create(instructor, null) as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Edit_Get_ReturnsBadRequest_WhenIdIsNull()
        {
            using var context = GetContext();
            var controller = new InstructorsController(context);

            var result = controller.Edit((int?)null);

            Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
        }

        [Fact]
        public void Edit_Get_ReturnsView_WhenInstructorExists()
        {
            using var context = GetContext();
            var controller = new InstructorsController(context);

            var result = controller.Edit(1) as ViewResult;

            Assert.NotNull(result);
            var instructor = result.Model as Instructor;
            Assert.Equal("Smith", instructor.LastName);
        }

        [Fact]
        public void Delete_Get_ReturnsBadRequest_WhenIdIsNull()
        {
            using var context = GetContext();
            var controller = new InstructorsController(context);

            var result = controller.Delete(null);

            Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
        }

        [Fact]
        public void Delete_Get_ReturnsNotFound_WhenInstructorNotFound()
        {
            using var context = GetContext();
            var controller = new InstructorsController(context);

            var result = controller.Delete(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_Get_ReturnsView_WhenInstructorExists()
        {
            using var context = GetContext();
            var controller = new InstructorsController(context);

            var result = controller.Delete(1) as ViewResult;

            Assert.NotNull(result);
            var instructor = result.Model as Instructor;
            Assert.Equal("Smith", instructor.LastName);
        }

        [Fact]
        public void DeleteConfirmed_RemovesInstructor_NullsDepartmentAdmin()
        {
            using var context = GetContext();
            var controller = new InstructorsController(context);

            var result = controller.DeleteConfirmed(1) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Empty(context.Instructors);
            // Department should have InstructorID nulled out
            var dept = context.Departments.First();
            Assert.Null(dept.InstructorID);
        }
    }
