using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;
using System;
using System.IO;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerTests
    {
        private CoursesController CreateController(SchoolContext context)
        {
            var env = new Mock<IWebHostEnvironment>();
            env.Setup(e => e.WebRootPath).Returns(Path.GetTempPath());
            env.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
            var logger = new Mock<ILogger<CoursesController>>();
            return new CoursesController(context, env.Object, logger.Object);
        }

        [Fact]
        public void Index_ReturnsView_WithCourses()
        {
            using var context = TestHelper.CreateSeededContext();
            var controller = CreateController(context);

            var result = controller.Index() as ViewResult;

            Assert.NotNull(result);
            var model = result.Model as System.Collections.Generic.List<Course>;
            Assert.NotNull(model);
            Assert.Equal(2, model.Count);
        }

        [Fact]
        public void Details_ReturnsBadRequest_WhenIdIsNull()
        {
            using var context = TestHelper.CreateSeededContext();
            var controller = CreateController(context);

            var result = controller.Details(null);

            Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
        }

        [Fact]
        public void Details_ReturnsView_WhenCourseExists()
        {
            using var context = TestHelper.CreateSeededContext();
            var controller = CreateController(context);

            var result = controller.Details(1050) as ViewResult;

            Assert.NotNull(result);
            var course = result.Model as Course;
            Assert.Equal("Chemistry", course.Title);
        }

        [Fact]
        public void Create_Get_ReturnsView()
        {
            using var context = TestHelper.CreateSeededContext();
            var controller = CreateController(context);

            var result = controller.Create() as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Create_Post_ValidCourse_RedirectsToIndex()
        {
            using var context = TestHelper.CreateSeededContext();
            var controller = CreateController(context);
            var deptId = context.Departments.First().DepartmentID;
            var course = new Course
            {
                CourseID = 9999,
                Title = "New Course",
                Credits = 4,
                DepartmentID = deptId
            };

            var result = controller.Create(course, null) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Equal(3, context.Courses.Count());
        }

        [Fact]
        public void Create_Post_InvalidModel_ReturnsView()
        {
            using var context = TestHelper.CreateSeededContext();
            var controller = CreateController(context);
            controller.ModelState.AddModelError("Title", "Required");
            var course = new Course { CourseID = 9999 };

            var result = controller.Create(course, null) as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Create_Post_WithInvalidFileExtension_ReturnsView()
        {
            using var context = TestHelper.CreateSeededContext();
            var controller = CreateController(context);
            var deptId = context.Departments.First().DepartmentID;
            var course = new Course
            {
                CourseID = 9999,
                Title = "New Course",
                Credits = 4,
                DepartmentID = deptId
            };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("test.exe");
            fileMock.Setup(f => f.Length).Returns(1024);

            var result = controller.Create(course, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.False(controller.ModelState.IsValid);
        }

        [Fact]
        public void Create_Post_WithOversizedFile_ReturnsView()
        {
            using var context = TestHelper.CreateSeededContext();
            var controller = CreateController(context);
            var deptId = context.Departments.First().DepartmentID;
            var course = new Course
            {
                CourseID = 9999,
                Title = "New Course",
                Credits = 4,
                DepartmentID = deptId
            };

            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("test.jpg");
            fileMock.Setup(f => f.Length).Returns(10 * 1024 * 1024); // 10MB

            var result = controller.Create(course, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.False(controller.ModelState.IsValid);
        }

        [Fact]
        public void Create_Post_WithValidImage_SavesFile()
        {
            using var context = TestHelper.CreateSeededContext();
            var controller = CreateController(context);
            var deptId = context.Departments.First().DepartmentID;
            var course = new Course
            {
                CourseID = 9999,
                Title = "New Course",
                Credits = 4,
                DepartmentID = deptId
            };

            var content = new byte[] { 0x89, 0x50, 0x4E, 0x47 };
            var stream = new MemoryStream(content);
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns("test.png");
            fileMock.Setup(f => f.Length).Returns(content.Length);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>())).Callback<Stream>(s => stream.CopyTo(s));

            var result = controller.Create(course, fileMock.Object) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            var saved = context.Courses.Find(9999);
            Assert.NotNull(saved.TeachingMaterialImagePath);
            Assert.Contains("/Uploads/TeachingMaterials/", saved.TeachingMaterialImagePath);
        }

        [Fact]
        public void Edit_Get_ReturnsBadRequest_WhenIdIsNull()
        {
            using var context = TestHelper.CreateSeededContext();
            var controller = CreateController(context);

            var result = controller.Edit((int?)null);

            Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
        }

