        {
            using var context = TestHelper.CreateSeededContext();
            var controller = CreateController(context);

            var result = controller.Edit(1050) as ViewResult;

            Assert.NotNull(result);
            var course = result.Model as Course;
            Assert.Equal("Chemistry", course.Title);
        }

