public void Enrollment_HasRelationships()
{
    using var context = TestHelper.CreateSeededContext();

    var enrollment = context.Enrollments.First();
    var course = context.Courses.Find(enrollment.CourseID);
    var student = context.Students.Find(enrollment.StudentID);

    Assert.NotNull(course);
    Assert.NotNull(student);
    Assert.Equal(Grade.A, enrollment.Grade);
}

